oxy_webhelp_navlinks = {"rubrik_backup_service-d39536e33864":{"topics":[{"title":"Obtaining Rubrik Backup Service connector","shortdesc":"<p class=\"shortdesc\">Download the Rubrik Backup Service connector to enable the connected Rubrik clusters         to restore folders and files over corrupted data in the file system on the host.<\/p>","href":"rbs\/rbs_obtaining_connector_3.html","attributes":{"data-id":"obtaining_rubrik_backup_service_connector"},"menu":{"hasChildren":false},"tocID":"obtaining_rubrik_backup_service_connector-d39536e33875","topics":[]},{"title":"Registering a virtual machine running RBS","shortdesc":"<p class=\"shortdesc\">After installing RBS on a virtual machine, register the virtual machine with <span class=\"ph\">RSC<\/span>. Registering the virtual machine enables <span class=\"ph\">RSC<\/span> to         coordinate backup operations with RBS.<\/p>","href":"saas\/registering_rbs_host_3.html","attributes":{"data-id":"registering_rbs_host"},"menu":{"hasChildren":false},"tocID":"registering_rbs_host-d39536e33886","topics":[]}]}};